import {H2} from '@jetbrains/ring-ui-built/components/heading/heading'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {skipToken} from '@reduxjs/toolkit/query'
import classNames from 'classnames'

import {useBuildHref} from '../../../../../hooks/routes'
import {useBuildStatusIcon} from '../../../../../hooks/useBuildStatusIcon'
import {useDetailedBuildTitle} from '../../../../../hooks/useBuildTitle'
import {getSingleBuildArg} from '../../../../../rest/builds'
import {getBuildLocator} from '../../../../../rest/locators'
import {restApi} from '../../../../../services/rest'
import {BuildStatusType} from '../../../../../types'
import Description from '../../../../common/Description/Description.container'
import Icon from '../../../../common/Icon/Icon'
import Loader from '../../../../common/Loader/Loader'

import type {Props} from './BuildLogPopupHeader.types'

import styles from './BuildLogPopupHeader.module.css'

export default function BuildLogPopupHeader({statusType, buildId, buildLoaded}: Props) {
  const title = useDetailedBuildTitle(buildId)
  const statusIcon = useBuildStatusIcon(buildId)
  restApi.endpoints.getBuildNormalized.useQuerySubscription(
    buildId != null ? getSingleBuildArg(getBuildLocator(buildId)) : skipToken,
  )
  const href = useBuildHref(buildId)
  return (
    <div className={styles.header}>
      {buildLoaded ? (
        <>
          <H2
            className={classNames(styles.title, {
              [styles.failure]: statusType === BuildStatusType.FAILURE,
              [styles.success]: statusType === BuildStatusType.SUCCESS,
            })}
          >
            {href != null && (
              <Link rel="noreferrer" target="_blank" href={href} className={styles.link}>
                <Icon name={statusIcon} className={styles.statusIcon} size="M" />
                {title}
              </Link>
            )}
          </H2>
          <Description
            lines={2}
            lineHeight={16}
            buildId={buildId}
            className={styles.description}
            textClassName={styles.descriptionText}
          />
        </>
      ) : (
        <Loader />
      )}
    </div>
  )
}
