import {connect} from 'react-redux'

import type {State} from '../../../../../reducers/types'
import {getBuildStatusType, isBuildLoaded} from '../../../../../selectors'
import {getFullLogState} from '../../BuildLog.selectors'
import {FullLogTarget} from '../../BuildLog.types'

import BuildLogPopupHeader from './BuildLogPopupHeader'
import type {StateProps} from './BuildLogPopupHeader.types'

const mapStateToProps = (state: State): StateProps => {
  const {buildId} = getFullLogState(state, FullLogTarget.POPUP)
  return {
    buildLoaded: Boolean(isBuildLoaded(state, buildId)),
    statusType: buildId != null ? getBuildStatusType(state, buildId) : null,
    buildId,
  }
}

export default connect(mapStateToProps)(BuildLogPopupHeader)
